update public.cultivars set origins = $j$[{"body":"Anthurium carlablackiae は 2020 年、Croat & O.Ortiz が Phytotaxa 467(1): 10 で記載した。タイプ産地は Puerto Obaldía, Comarca Guna Yala, Panama。採集者は T. B. Croat（2009 年採集）。分布は Colombia, Panama（POWO）。種小名はパナマ・チリキ県の園芸家 Carla Black への献名（IPNI）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-04-02","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium carlablackiae was described by Croat & O.Ortiz in 2020 in Phytotaxa 467(1): 10. Type locality: Puerto Obaldía, Comarca Guna Yala, Panama. Collected by T. B. Croat (2009). Distribution: Colombia, Panama (POWO). The epithet honours Carla Black, a horticulturist in Chiriquí Province, Panama (IPNI).","sources":[{"url":"https://www.ipni.org/n/77212524-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77212524-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77212524-1","structured":{"notes":"","collector":"T. B. Croat","author_name":"Croat & O.Ortiz","origin_type":"species","type_locality":"Puerto Obaldía, Comarca Guna Yala, Panama","citation_links":[{"url":"https://www.ipni.org/n/77212524-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77212524-1","label":"POWO (Kew)"}],"known_habitats":"Colombia, Panama","collection_year":2009,"publication_year":2020},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Colombia, Panama","discovery_year":2020,"source_language":"en","first_description":"Croat & O.Ortiz, Phytotaxa 467(1): 10 (2020)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Croat & O.Ortiz"}]$j$::jsonb, name_status = null, aliases = null, tags = null, formula_status = null, updated_at = now() where id = 1;
