update public.cultivars set origins = $j$[{"body":"Anthurium 'Ace of Spades' は、フロリダのナーセリーである The Orchid Jungle にて管理されていた、南米採集の未同定株に由来する選抜個体である。\n\nこの母株は当初 Anthurium hoffmannii としてラベルされていたが、形態的特徴からその同定には疑問があり、正確な種同定はされていない。\n\n採集地では単独で存在していたとされ、自家受粉、もしくは自然交雑により得られた種子から実生が育成された。その後、Denis Rotolante によって播種され、得られた実生群の中から特に優れた形質を持つ個体が選抜され 'Ace of Spades' と命名された。\n\nそのため本個体は明確な交配式を持つ人工交配種ではなく、自然由来の遺伝背景を持つ実生選抜クローンと考えられている。","trust":23,"votes":{"agree":1,"disagree":0},"author":{"isAI":false,"name":"User"},"body_en":null,"sources":[],"verified":false,"parentage":null,"source_url":null,"structured":{"namer":"Denis Rotolante","notes":"Anthurium 'Ace of Spades' は、フロリダのナーセリーである The Orchid Jungle にて管理されていた、南米採集の未同定株に由来する選抜個体である。\n\nこの母株は当初 Anthurium hoffmannii としてラベルされていたが、形態的特徴からその同定には疑問があり、正確な種同定はされていない。\n\n採集地では単独で存在していたとされ、自家受粉、もしくは自然交雑により得られた種子から実生が育成された。その後、Denis Rotolante によって播種され、得られた実生群の中から特に優れた形質を持つ個体が選抜され 'Ace of Spades' と命名された。\n\nそのため本個体は明確な交配式を持つ人工交配種ではなく、自然由来の遺伝背景を持つ実生選抜クローンと考えられている。 所属: Silver Krome Gardens (SKG)。","collector":null,"naming_year":null,"origin_type":"clone","citation_links":[]},"trustClass":"trust--low","source_name":null,"source_tier":"D","source_type":"manual","native_region":null,"discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Unknown / Unverified","source_tier_label_jp":"不明・未検証","discoverer_or_breeder":"Denis Rotolante"}]$j$::jsonb, name_status = null, aliases = null, tags = null, formula_status = $q$unknown$q$, updated_at = now() where id = 7;
