update public.cultivars set origins = $j$[{"body":"Anthurium kunayalense は 2010 年、Croat & Vannini が Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C) で記載した。タイプ産地は El Llano–Cartí road, Panamá Province, Panama。採集者は T. B. Croat & J. Vannini（2009 年採集）。分布は Panama（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium kunayalense was described by Croat & Vannini in 2010 in Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C). Type locality: El Llano–Cartí road, Panamá Province, Panama. Collected by T. B. Croat & J. Vannini (2009). Distribution: Panama (POWO).","sources":[{"url":"https://www.ipni.org/n/77107445-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","structured":{"notes":"","collector":"T. B. Croat & J. Vannini","author_name":"Croat & Vannini","origin_type":"species","type_locality":"El Llano–Cartí road, Panamá Province, Panama","citation_links":[{"url":"https://www.ipni.org/n/77107445-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:77107445-1","label":"POWO (Kew)"}],"known_habitats":"Panama","collection_year":2009,"publication_year":2010},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Panama","discovery_year":2010,"source_language":"en","first_description":"Croat & Vannini, Aroideana 33: 162 (-164, 166; figs. 1A-D, 2A-C) (2010)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"Croat & Vannini"}]$j$::jsonb, name_status = null, aliases = null, tags = null, formula_status = null, updated_at = now() where id = 38;
