update public.cultivars set origins = $j$[{"body":"正式な学名記載はまだない（未記載種／暫定名）。東パナマ産の黒いベルベット葉群として園芸界に現れ、BVEP（Black Velvet Eastern Panama）として流通した個体群を基にしている。園芸・収集界の記録ではRory Antolak が現地材料を導入・維持し、antolakii の暫定名を用いるようになったとされる。Jay Vannini 等が ined.（未出版名）として扱っている旨の専門家記事がある一方、IPNI/POWO/Tropicos 等の正式登録には有効な記載が見つからない。近縁関係は A. dressleri 群や papillilaminum 系と比較されることが多く、分布情報の公開を避けるため出典間で差異がある。","trust":67,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-09-04","isAI":true,"name":"AI (gpt-5-mini + Web検索)"},"body_en":"Formal, published nomenclature for Anthurium antolakii is not available — the name is used provisionally in cultivation. The plant entered the hobby as \"BVEP\" (Black Velvet Eastern Panama), appearing in trade around 2020. Multiple dealer and expert accounts credit Rory Antolak with introducing and maintaining the wild material; Jay Vannini and others have referred to the taxon as A. \"antolakii\" (ined.) in specialist writing. No valid protologue or IPNI/POWO/Tropicos record has been found, so the name remains unpublished. Horticultural sources commonly compare this entity to velvet-leaf species (notably Anthurium dressleri and papillilaminum-like plants). Locality information is treated confidentially by collectors, and some secondary sources disagree about whether a formal publication exists or whether a Tropicos listing was temporary.","sources":[{"url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","label":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)"}],"verified":false,"parentage":null,"source_url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","structured":{"notes":"産地は東パナマ（Guna Yala 高地が示唆される）。","collector":null,"author_name":null,"origin_type":"species","trade_names":["BVEP","Black Velvet Eastern Panama"],"introduced_by":"Rory Antolak が導入・維持（2020頃）","origin_region":"Panama（eastern; Guna Yala 高地が示唆される）","type_locality":null,"citation_links":[{"url":"https://www.exoticaesoterica.com/magazine/the-ultimate-guide-to-velvet-leaf-anthuriums","label":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)"}],"known_habitats":"Panama","species_status":"undescribed","closest_species":"Anthurium dressleri","collection_year":null,"first_seen_year":2020,"publication_year":null,"working_name_origin":"Rory Antolak に献名した暫定学名（antolakii）"},"trustClass":"trust--mid","source_name":"Exotica Esoterica — \"The Ultimate Guide to Velvet Leaf Anthuriums\" (Jay Vannini)","source_tier":"B","source_type":"ai_research","native_region":"Panama","discovery_year":null,"source_language":"en","first_description":null,"source_tier_label_en":"Horticultural Books / Society Publications","source_tier_label_jp":"園芸書籍・学会資料","discoverer_or_breeder":null}]$j$::jsonb, name_status = $q$informal$q$, aliases = array[$q$BVEP$q$,$q$Black Velvet Eastern Panama$q$]::text[], tags = array[$q$undescribed$q$]::text[], formula_status = null, updated_at = now() where id = 59;
update public.cultivars set origins = $j$[{"body":"Anthurium wendlingeri は 1965 年、G.M.Barroso が Bol. Soc. Venez. Ci. Nat. 26: 151, fig で記載した。タイプ産地は Costa Rica。分布は Panama, Colombia, Costa Rica, Nicaragua（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-16","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium wendlingeri was described by G.M.Barroso in 1965 in Bol. Soc. Venez. Ci. Nat. 26: 151, fig. Type locality: Costa Rica. Distribution: Panama, Colombia, Costa Rica, Nicaragua (POWO).","sources":[{"url":"https://www.ipni.org/n/15824-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15824-2","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15824-2","structured":{"notes":"","collector":null,"author_name":"G.M.Barroso","origin_type":"species","type_locality":"Costa Rica","citation_links":[{"url":"https://www.ipni.org/n/15824-2","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:15824-2","label":"POWO (Kew)"}],"known_habitats":"Panama, Colombia, Costa Rica, Nicaragua","collection_year":null,"publication_year":1965},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"Panama, Colombia, Costa Rica, Nicaragua","discovery_year":1965,"source_language":"en","first_description":"G.M.Barroso, Bol. Soc. Venez. Ci. Nat. 26: 151, fig (1965)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"G.M.Barroso"}]$j$::jsonb, name_status = null, aliases = null, tags = null, formula_status = null, updated_at = now() where id = 77;
update public.cultivars set origins = $j$[{"body":"Anthurium sagittatum は 1839 年、G.Don が Sweet's Hort. Brit., ed. 3. 633 で Pothos sagittatus Sims を Anthurium に組み替えた名前。分布は French Guiana, Guyana, Colombia, Brazil, Peru, Suriname, Venezuela（POWO）。","trust":95,"votes":{"agree":0,"disagree":0},"author":{"date":"2026-03-17","isAI":true,"name":"IPNI / POWO"},"body_en":"Anthurium sagittatum is G.Don's 1839 transfer of Pothos sagittatus Sims to Anthurium in Sweet's Hort. Brit., ed. 3. 633. Distribution: French Guiana, Guyana, Colombia, Brazil, Peru, Suriname, Venezuela (POWO).","sources":[{"url":"https://www.ipni.org/n/85321-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85321-1","label":"POWO (Kew)"}],"verified":true,"parentage":null,"source_url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85321-1","structured":{"notes":"","collector":null,"author_name":"(Sims) G.Don","origin_type":"species","type_locality":null,"citation_links":[{"url":"https://www.ipni.org/n/85321-1","label":"IPNI"},{"url":"https://powo.science.kew.org/taxon/urn:lsid:ipni.org:names:85321-1","label":"POWO (Kew)"}],"known_habitats":"French Guiana, Guyana, Colombia, Brazil, Peru, Suriname, Venezuela","collection_year":null,"publication_year":1839,"basionym":"Pothos sagittatus Sims"},"trustClass":"trust--high","source_name":"IPNI / POWO (Kew Gardens)","source_tier":"S","source_type":"ipni_powo","native_region":"French Guiana, Guyana, Colombia, Brazil, Peru, Suriname, Venezuela","discovery_year":1839,"source_language":"en","first_description":"(Sims) G.Don, Sweet's Hort. Brit., ed. 3. 633 (1839)","source_tier_label_en":"IPNI / POWO (Kew)","source_tier_label_jp":"IPNI / POWO（キュー王立植物園）","discoverer_or_breeder":"(Sims) G.Don"}]$j$::jsonb, name_status = null, aliases = null, tags = null, formula_status = null, updated_at = now() where id = 82;
