update public.cultivars set origins = $j$[{"body":"作出者: Chandra. 交配式: 'Dorayaki' original × 'Red Crystallinum' NSE. Anthurium 'Mystique A88' は Chandra によって作出された。Anthurium 'Dorayaki' original と Anthurium 'Red Crystallinum' NSE の交配式である\n\n'Mystique A88' にはoriginalがある。しかし生産ラインはoriginalのseedlingではなく、\n'Dorayaki' original×'Red Crystallinum' NSE\nのF1個体になる。","trust":30,"votes":{"agree":1,"disagree":0},"author":{"date":"2026-03-30","isAI":false,"name":"User"},"sources":[],"structured":{"notes":"Anthurium 'Mystique A88' は Mr Chandra によって作出された。Anthurium 'Dorayaki' original と Anthurium 'Red Crystallinum' NSE の交配式である\n\n'Mystique A88' にはoriginalがある。しかし生産ラインはoriginalのseedlingではなく、\n'Dorayaki' original×'Red Crystallinum' NSE\nのF1個体になる。 母株は 'Red Crystallinum' の NSE 系統。","breeder":"Chandra","formula":{"parentA":"Anthurium 'Dorayaki'","parentB":"Anthurium 'Red Crystallinum'"},"collector":null,"origin_type":"hybrid"},"trustClass":"trust--low","source_type":"manual","discoverer_or_breeder":"Chandra"}]$j$::jsonb, name_status = null, aliases = array[$q$Mystique a88$q$]::text[], tags = null, formula_status = $q$known$q$, updated_at = now() where id = 109;
